    """
    Transform function for task-b1914027.

    Rule:
    1. Find all solid 3x3 blocks of non-zero color
    2. Each block spawns a full vertical line (center column) and horizontal line (center row) of its color
    3. When lines intersect, the cell becomes 0
    4. Non-line cells retain their original value
    """
    grid = np.array(grid)
    h, w = grid.shape

    # Find all solid 3x3 blocks
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            block = grid[r:r+3, c:c+3]
            if np.all(block > 0) and np.all(block == block[0,0]):
                center_r, center_c = r + 1, c + 1
                blocks.append((center_r, center_c, int(block[0,0])))

    if not blocks:
        # Return original grid if no blocks
        return grid.tolist()

    # Create lines dictionary
    lines = {}
    for cr, cc, color in blocks:
        # Add vertical line at col cc
        for r in range(h):
            lines[(r, cc)] = color
        # Add horizontal line at row cr
        for c in range(w):
            lines[(cr, c)] = color

    # Note: when we just assign, later blocks overwrite earlier ones
    # But we need to handle intersections specially (result should be 0)

    # Apply the transform
    result = grid.copy()
    for r in range(h):
        for c in range(w):
            if (r, c) in lines:
                color = lines[(r, c)]
                # Check if this is an intersection (multiple lines)
                # Count how many different lines pass through this cell
                count = 0
                for other_cr, other_cc, other_color in blocks:
                    if (r == other_cr or c == other_cc):
                        count += 1
                if count > 1:
                    result[r, c] = 0
                else:
                    result[r, c] = color

    return result.tolist()

